    int limit = 0;
    if (desiredCapacity >= 1000) {
        limit = (int)(desiredCapacity * 1.11);
    }
    while (true) {
        // check if candidate is prime
        if (candidate < 2) {
            candidate = 2;
        } else {
            boolean isPrime = true;
            if (candidate == 2) {
                isPrime = true;
            } else {
                if (candidate % 2 == 0) {
                    isPrime = false;
                } else {
                    int sqrt = (int)Math.sqrt(candidate);
                    for (int i = 3; i <= sqrt; i += 2) {
                        if (candidate % i == 0) {
                            isPrime = false;
                            break;
                        }
                    }
                }
            }
            if (isPrime) return candidate;
        }
        candidate += 2; // next odd number
        if (limit != 0 && candidate > limit) {
            // if exceeded threshold, return what we have found so far (odd candidate)
